/* Frontier Graph - Flows view: d3.chord diagram of moves between orgs (employment history).
   Loaded after app.js; uses window.FG. Everything here is optional: with no flows in the data the view shows an empty state. */
'use strict';
(() => {
const FG = window.FG;
if (!FG) return;
const { S, esc, orgColor, orgName, isLabOrg, labColor, plural, NEUTRAL } = FG;
const MAX_GROUPS = 8, ARC_W = 14;
let svgF, gRoot, gRib, gArc, gLbl, ribSel, arcSel, lblSel;
let D = null, pick = null;               // D: last build (groups, pairs, matrix); pick: {t:'pair', a, b} | {t:'group', id} (group ids, not indices)
let stat = { moves: 0, people: 0, undated: 0 }, hadFlows = false;
const directed = () => !!(d3.chordDirected && d3.ribbonArrow);
const people = n => plural(n, 'person').replace('persons', 'people');

// ---- data -> groups, pair aggregates, matrix
function filtered() {
  const [y0, y1] = S.years;
  return S.flows.filter(f => f.year == null ? S.undated : (f.year >= y0 && f.year <= y1));
}

function build() {
  const fl = filtered(), tot = new Map();
  fl.forEach(f => { tot.set(f.from, (tot.get(f.from) || 0) + f.count); tot.set(f.to, (tot.get(f.to) || 0) + f.count); });
  const labIds = S.labs.map(l => l.id).filter(isLabOrg);
  const ext = [...tot].filter(([id]) => !isLabOrg(id)).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  const room = MAX_GROUPS - labIds.length;
  const keep = ext.length <= room ? ext : ext.slice(0, Math.max(0, room - 1));
  const groups = labIds.map(id => ({ id, members: [id], label: orgName(id), color: orgColor(id), lab: true }));
  keep.forEach(([id]) => groups.push({ id, members: [id], label: orgName(id), color: orgColor(id), lab: false }));
  const rest = ext.slice(keep.length);
  if (rest.length) groups.push({ id: '__other', members: rest.map(r => r[0]), label: groups.some(g => g.label === 'Other') ? 'Other (merged)' : 'Other', color: NEUTRAL, lab: false });
  const gi = new Map();
  groups.forEach((g, i) => g.members.forEach(m => gi.set(m, i)));
  const pairs = new Map();              // "i>j" -> {i, j, flows, ids, anon}
  const all = new Set();
  let moves = 0, undated = 0, anonAll = 0;
  fl.forEach(f => {
    const i = gi.get(f.from), j = gi.get(f.to);
    moves += f.count; if (f.year == null) undated += f.count;
    f.people.forEach(id => all.add(id)); anonAll += Math.max(0, f.count - f.people.length);
    if (i == null || j == null) return;
    const k = i + '>' + j;
    if (!pairs.has(k)) pairs.set(k, { i, j, flows: [], ids: new Set(), anon: 0 });
    const p = pairs.get(k);
    p.flows.push(f); f.people.forEach(id => p.ids.add(id)); p.anon += Math.max(0, f.count - f.people.length);
  });
  const n = groups.length, matrix = Array.from({ length: n }, () => Array(n).fill(0));
  pairs.forEach(p => { p.n = p.ids.size + p.anon; matrix[p.i][p.j] = p.n; });
  stat = { moves, people: all.size + anonAll, undated };
  hadFlows = pairs.size > 0;
  D = { groups, gi, pairs, matrix, fl };
}

// ---- helpers
const yearsOf = flows => {
  const ys = flows.filter(f => f.year != null).map(f => f.year), und = flows.some(f => f.year == null);
  const lo = Math.min(...ys), hi = Math.max(...ys), span = ys.length ? (lo === hi ? `${lo}` : `${lo}–${hi}`) : '';
  return span ? (und ? span + ' + undated' : span) : 'undated';
};
// directed chords map to one i>j pair; the undirected d3.chord fallback merges both directions
const pairsFor = (i, j) => (directed() ? [D.pairs.get(i + '>' + j)] : [D.pairs.get(i + '>' + j), i === j ? null : D.pairs.get(j + '>' + i)]).filter(Boolean);
const pairInfo = (i, j) => {
  const ps = pairsFor(i, j), ids = new Set(ps.flatMap(p => [...p.ids])), anon = ps.reduce((a, p) => a + p.anon, 0);
  return { flows: ps.flatMap(p => p.flows), n: ids.size + anon };
};
const arrow = () => directed() ? '→' : '↔';
const groupById = id => D.groups.findIndex(g => g.id === id);
const labHi = i => D.groups[i].lab && S.hiLabs.has(D.groups[i].id);

// ---- drawing
function ensureSvg() {
  if (svgF) return;
  svgF = d3.select('#flows-svg');
  gRoot = svgF.append('g').attr('class', 'root');
  gRib = gRoot.append('g'); gArc = gRoot.append('g'); gLbl = gRoot.append('g');
  svgF.on('click', ev => { if (ev.target === svgF.node()) FG.clearSel(); });
}

function draw() {
  if (!D) return;
  ensureSvg();
  gRib.selectAll('*').remove(); gArc.selectAll('*').remove(); gLbl.selectAll('*').remove();
  ribSel = arcSel = lblSel = null;
  if (!hadFlows) return;
  const [w, h] = FG.stageSize(), R = Math.max(70, Math.min((w - 380) / 2, (h - 90) / 2));
  const chords = (directed() ? d3.chordDirected() : d3.chord()).padAngle(0.06).sortSubgroups(d3.descending)(D.matrix);
  const arc = d3.arc().innerRadius(R).outerRadius(R + ARC_W);
  const rib = (directed() ? d3.ribbonArrow() : d3.ribbon()).radius(R - 2);
  const grp = [...chords.groups].filter(g => g.value > 0);

  ribSel = gRib.selectAll('path').data([...chords]).join('path').attr('class', 'ribbon')
    .attr('d', rib).attr('fill', c => D.groups[c.source.index].color)
    .on('mouseenter', function (ev, c) {
      d3.select(this).classed('hov', true).raise();
      const q = pairInfo(c.source.index, c.target.index);
      FG.showTip(ev, `<b>${esc(D.groups[c.source.index].label)} ${arrow()} ${esc(D.groups[c.target.index].label)} · ${people(q.n)} (${esc(yearsOf(q.flows))})</b>`);
    })
    .on('mousemove', FG.moveTip)
    .on('mouseleave', function () { d3.select(this).classed('hov', false); FG.hideTip(); })
    .on('click', (ev, c) => { ev.stopPropagation(); setPick({ t: 'pair', a: D.groups[c.source.index].id, b: D.groups[c.target.index].id }, true); });

  arcSel = gArc.selectAll('path').data(grp).join('path').attr('class', 'garc').attr('d', arc).attr('fill', g => D.groups[g.index].color)
    .on('mouseenter', (ev, g) => {
      const i = g.index, out = d3.sum(D.matrix[i]), inn = d3.sum(D.matrix, r => r[i]);
      FG.showTip(ev, `<b>${esc(D.groups[i].label)}</b><span>${inn} moved in · ${out} moved out</span>`);
    })
    .on('mousemove', FG.moveTip).on('mouseleave', FG.hideTip)
    .on('click', (ev, g) => { ev.stopPropagation(); setPick({ t: 'group', id: D.groups[g.index].id }, true); });

  lblSel = gLbl.selectAll('text').data(grp).join('text').attr('class', 'glabel').each(function (g) {
    const a = (g.startAngle + g.endAngle) / 2 - Math.PI / 2, r = R + ARC_W + 8, label = D.groups[g.index].label;
    d3.select(this).attr('x', r * Math.cos(a)).attr('y', r * Math.sin(a)).attr('text-anchor', Math.cos(a) >= -0.05 ? 'start' : 'end')
      .text(label.length > 24 ? label.slice(0, 23) + '…' : label);
  });
  recenter(true); paint();
}

function recenter(instant) {                         // centre the diagram in the part of the stage the drawer leaves free
  if (!gRoot) return;
  const [w, h] = FG.stageSize(), [cx, cy] = FG.viewCenter(), s = Math.min(1, 2 * cx / w, 2 * cy / h);
  if (instant) gRoot.style('transition', 'none');
  gRoot.style('transform', `translate(${cx}px,${cy}px) scale(${s})`);
  if (instant) { gRoot.node().getBoundingClientRect(); gRoot.style('transition', null); }
}

// emphasis from lab chips and the current pick. Hover uses its own 'hov' class and is never touched here.
function paint() {
  if (!ribSel || !D) return;
  const hi = S.hiLabs.size > 0, pk = pick && resolve(pick), grpPick = pk && pk.t === 'group', pairPick = pk && pk.t === 'pair';
  ribSel.classed('dim', c => { const i = c.source.index, j = c.target.index; return grpPick ? !(i === pk.i || j === pk.i) : hi && !(labHi(i) || labHi(j)); })
    .classed('sel', c => !!pairPick && c.source.index === pk.i && c.target.index === pk.j);
  arcSel.classed('dim', g => (hi && D.groups[g.index].lab && !labHi(g.index)) || (grpPick && pk.i !== g.index))
    .classed('sel', g => !!grpPick && pk.i === g.index);
  lblSel.classed('dim', g => hi && D.groups[g.index].lab && !labHi(g.index));
}

function resolve(p) {                                // group ids -> indices in the current build, or null when gone
  if (p.t === 'group') { const i = groupById(p.id); return i < 0 ? null : { t: 'group', i }; }
  const i = groupById(p.a), j = groupById(p.b);
  return i < 0 || j < 0 || !pairsFor(i, j).length ? null : { t: 'pair', i, j };
}

// ---- drawer
const confOf = (id, f) => {
  const st = S.byId.get(id)?.history.find(h => h.org === f.to && (f.year == null ? h.start == null : h.start && +String(h.start).slice(0, 4) === f.year));
  return st?.confidence || f.conf || '';
};
function personRow(id, f, note) {
  const n = S.byId.get(id), c = confOf(id, f);
  const who = n ? `<span class="dot" style="--c:${esc(labColor(n.lab))}"></span><button class="go" data-go="${esc(id)}">${esc(n.name)}</button>`
    : `<span class="dot"></span><span class="go">${esc(id.replace(/^[^:]*:/, ''))}</span>`;
  return `<li>${who}<span class="yr">${esc(f.year ?? 'undated')}</span>${note ? `<span class="cmeta">${esc(note)}</span>` : ''}${c ? `<span class="conf conf-${esc(c.replace(/[^a-z]/g, ''))}" title="Confidence: ${esc(c)}">${esc(c)}</span>` : ''}</li>`;
}
const rowsOf = (flows, noteFn) => flows.flatMap(f => f.people.map(id => ({ id, f, name: S.byId.get(id)?.name || id })))
  .sort((a, b) => (b.f.year ?? -1) - (a.f.year ?? -1) || a.name.localeCompare(b.name))
  .map(r => personRow(r.id, r.f, noteFn && noteFn(r.f))).join('');
const more = flows => { const k = flows.reduce((a, f) => a + Math.max(0, f.count - f.people.length), 0); return k ? `<li class="empty">…and ${k} more not listed</li>` : ''; };

function showDrawer() {
  const pk = pick && resolve(pick);
  if (!pk) return;
  if (pk.t === 'pair') {
    const a = D.groups[pk.i], b = D.groups[pk.j], q = pairInfo(pk.i, pk.j);
    FG.openDrawer(`<h2>${esc(a.label)} ${arrow()} ${esc(b.label)}</h2>
      <p class="facts"><b>${people(q.n)}</b> · ${esc(yearsOf(q.flows))}</p>
      <h4>People</h4><ul class="plain">${rowsOf(q.flows)}${more(q.flows)}</ul>`);
  } else {
    const g = D.groups[pk.i], inn = D.fl.filter(f => D.gi.get(f.to) === pk.i), out = D.fl.filter(f => D.gi.get(f.from) === pk.i);
    const cnt = fs => new Set(fs.flatMap(f => f.people)).size + fs.reduce((a, f) => a + Math.max(0, f.count - f.people.length), 0);
    FG.openDrawer(`<h2><span class="dot" style="--c:${esc(g.color)}"></span> ${esc(g.label)}</h2>${g.members.length > 1 ? `<p class="facts">${g.members.length} orgs merged: ${esc(g.members.map(orgName).join(', '))}</p>` : ''}
      <h4>Moved in (${cnt(inn)})</h4><ul class="plain">${rowsOf(inn, f => 'from ' + orgName(f.from)) || '<li class="empty">None.</li>'}${more(inn)}</ul>
      <h4>Moved out (${cnt(out)})</h4><ul class="plain">${rowsOf(out, f => 'to ' + orgName(f.to)) || '<li class="empty">None.</li>'}${more(out)}</ul>`);
  }
}

function setPick(p, open) {
  pick = p; paint();
  if (p && open) showDrawer();
}

// ---- public surface (used by app.js)
function update() {                                  // filters changed or view entered: rebuild, redraw, refresh the open drawer
  build(); draw();
  if (pick && !resolve(pick)) { pick = null; FG.closeDrawer(); } else if (pick) showDrawer();
}
function leave() { pick = null; FG.hideTip(); }
function message() {
  if (!S.flows.length) return 'No employment history in this dataset';
  return hadFlows ? '' : 'No moves match the current filters.';
}
FG.Flows = { update, leave, draw, recenter: () => recenter(false), pick: p => setPick(p, false), stats: () => stat, message };
})();
